-- AD2 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD02.sql.
SELECT 'all 16 new AD2 tables exist with RLS enabled and forced' AS rule, (SELECT count(*) FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relkind = 'r' AND c.relrowsecurity AND c.relforcerowsecurity AND c.relname IN ('fadm_ledger_kind','fadm_relation','fadm_action','fadm_unit','fadm_rel','fadm_shift','fadm_ip_allow','fadm_policy','fadm_aaguid_allow','fadm_enroll_token','fadm_recovery','fadm_recovery_approval','fadm_elevation','fadm_burst_limit','fadm_burst','fadm_alert')) = 16 AS ok
UNION ALL SELECT 'every desk table is fadm_* with RLS enabled and forced', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relkind = 'r' AND (c.relname NOT LIKE 'fadm\_%' OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity))
UNION ALL SELECT 'desk_app has no write on any AD2 table', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relname IN ('fadm_ledger_kind','fadm_relation','fadm_action','fadm_unit','fadm_rel','fadm_shift','fadm_ip_allow','fadm_policy','fadm_aaguid_allow','fadm_enroll_token','fadm_recovery','fadm_recovery_approval','fadm_elevation','fadm_burst_limit','fadm_burst','fadm_alert') AND has_table_privilege('desk_app', c.oid, 'INSERT,UPDATE,DELETE'))
UNION ALL SELECT 'staff cannot hold a password (constraint)', EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fadm_owner_pw_by_role')
UNION ALL SELECT 'staff must be passkey_required (constraint)', EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fadm_owner_staff_passkey')
UNION ALL SELECT 'ledger kind list guard fires before the chain', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_ledger'::regclass AND tgname = 'fadm_ledger_00kind')
UNION ALL SELECT 'relation tuples cannot be deleted or edited (guard trigger)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_rel'::regclass AND tgname = 'fadm_rel_guard')
UNION ALL SELECT 'passkey guard trigger present (device-bound, allow-list)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_passkey'::regclass AND tgname = 'fadm_passkey_guard')
UNION ALL SELECT 'the three first teams exist', (SELECT count(*) FROM desk.fadm_unit WHERE kind = 'team' AND slug IN ('support','migration','frontend_demo')) = 3
UNION ALL SELECT 'relations are a strict order of six', (SELECT count(DISTINCT rank) FROM desk.fadm_relation) = 6
UNION ALL SELECT 'policies: 14 permits and a forbid for each lock', (SELECT count(*) FROM desk.fadm_policy WHERE effect = 'permit') >= 14 AND (SELECT count(*) FROM desk.fadm_policy WHERE effect = 'forbid') >= 8
UNION ALL SELECT 'no permit policy without a relation', NOT EXISTS (SELECT 1 FROM desk.fadm_policy WHERE effect = 'permit' AND relation IS NULL)
UNION ALL SELECT 'every owner-role person is admin of the root department', NOT EXISTS (SELECT 1 FROM desk.fadm_owner o WHERE o.role = 'owner' AND NOT desk.fadm_check(o.id, 'unit', desk.fadm_unit_id('department','desk'), 'admin'))
UNION ALL SELECT 'no standing elevation tuple (they all expire)', NOT EXISTS (SELECT 1 FROM desk.fadm_rel WHERE source <> 'direct' AND expires_at IS NULL)
UNION ALL SELECT 'enrol codes live at most 15 minutes', NOT EXISTS (SELECT 1 FROM desk.fadm_enroll_token WHERE expires_at > created_at + interval '15 minutes')
UNION ALL SELECT 'every recovery cools at least 24 hours', NOT EXISTS (SELECT 1 FROM desk.fadm_recovery WHERE cool_until < opened_at + interval '24 hours')
UNION ALL SELECT 'no live staff passkey that is synced or off the allow-list', NOT EXISTS (SELECT 1 FROM desk.fadm_passkey k JOIN desk.fadm_owner o ON o.id = k.owner_id WHERE o.role = 'agent' AND k.revoked_at IS NULL AND (k.backup_eligible IS DISTINCT FROM false OR k.aaguid NOT IN (SELECT aaguid FROM desk.fadm_aaguid_allow WHERE enabled)))
UNION ALL SELECT 'no PUBLIC execute on Desk functions', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.proname LIKE 'fadm\_%' AND has_function_privilege('public', p.oid, 'EXECUTE') AND p.prorettype <> 'trigger'::regtype)
UNION ALL SELECT 'all SECURITY DEFINER functions pin search_path', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.prosecdef AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')))
UNION ALL SELECT 'ledger hash chain still verifies', desk.fadm_ledger_verify();
